<?php
/**
 * Cockpit Automatic Full Data Importer & Schema Builder for FADAKAR Portfolio
 * Place this file inside cms.fadakar-dev.ir and open https://cms.fadakar-dev.ir/seed.php in your browser.
 */

ini_set('display_errors', 1);
error_reporting(E_ALL);
header('Content-Type: text/html; charset=utf-8');

if (!file_exists(__DIR__ . '/bootstrap.php')) {
    die('<div style="direction:rtl; font-family:tahoma; padding:20px; color:red;"><h2>خطا: فایل bootstrap.php پیدا نشد!</h2><p>مطمئن شوید فایل seed.php را دقیقاً داخل پوشه اصلی cms.fadakar-dev.ir قرار داده‌اید.</p></div>');
}

include_once __DIR__ . '/bootstrap.php';
$cockpit = Cockpit::instance();
$content = $cockpit->module('content');

echo '<div style="direction:rtl; font-family:system-ui, -apple-system, sans-serif; max-width:850px; margin:40px auto; padding:35px; border:1px solid #e2e8f0; border-radius:18px; background:#fff; box-shadow:0 15px 35px rgba(0,0,0,0.06); line-height:2.2;">';
echo '<h2 style="color:#6366f1; margin-top:0;">⚡ در حال انتقال کامل اطلاعات و مدل‌ها به دیتابیس Cockpit...</h2>';

// 1. Create / Update articles Model
$articleModel = [
    'name' => 'articles',
    'label' => 'مقالات (Articles)',
    'type' => 'collection',
    'fields' => [
        ['name' => 'slug', 'label' => 'شناسه آدرس (Slug)', 'type' => 'text', 'required' => true],
        ['name' => 'title', 'label' => 'عنوان مقاله (فارسی)', 'type' => 'text', 'required' => true],
        ['name' => 'titleEn', 'label' => 'Article Title (English)', 'type' => 'text', 'required' => true],
        ['name' => 'category', 'label' => 'دسته‌بندی (فارسی)', 'type' => 'text'],
        ['name' => 'categoryEn', 'label' => 'Category (English)', 'type' => 'text'],
        ['name' => 'excerpt', 'label' => 'خلاصه مقاله (فارسی)', 'type' => 'textarea'],
        ['name' => 'excerptEn', 'label' => 'Article Excerpt (English)', 'type' => 'textarea'],
        ['name' => 'accent', 'label' => 'رنگ هاله (Hex Color)', 'type' => 'color'],
        ['name' => 'date', 'label' => 'تاریخ انتشار', 'type' => 'text'],
        ['name' => 'readTime', 'label' => 'زمان مطالعه (دقیقه)', 'type' => 'number'],
        ['name' => 'content', 'label' => 'متن کامل مقاله (فارسی)', 'type' => 'wysiwyg'],
        ['name' => 'contentEn', 'label' => 'Full Content (English)', 'type' => 'wysiwyg']
    ]
];

try {
    $content->createModel('articles', $articleModel);
    echo '<p style="color:#16a34a; font-weight:bold;">✓ کالکشن مقالات (articles) با ۱۲ فیلد تخصصی ساخته شد.</p>';
} catch (Throwable $e) {
    echo '<p style="color:#64748b;">ℹ وضعیت کالکشن مقالات: ' . htmlspecialchars($e->getMessage()) . '</p>';
}

// 2. Create / Update services Model
$serviceModel = [
    'name' => 'services',
    'label' => 'خدمات (Services)',
    'type' => 'collection',
    'fields' => [
        ['name' => 'title', 'label' => 'عنوان خدمت (فارسی)', 'type' => 'text', 'required' => true],
        ['name' => 'titleEn', 'label' => 'Service Title (English)', 'type' => 'text', 'required' => true],
        ['name' => 'short', 'label' => 'توضیح کوتاه (فارسی)', 'type' => 'textarea'],
        ['name' => 'shortEn', 'label' => 'Short Description (English)', 'type' => 'textarea'],
        ['name' => 'detail', 'label' => 'جزئیات خدمت (فارسی)', 'type' => 'textarea'],
        ['name' => 'detailEn', 'label' => 'Service Details (English)', 'type' => 'textarea'],
        ['name' => 'accent', 'label' => 'رنگ هاله کارت (Hex Color)', 'type' => 'color'],
        ['name' => 'link', 'label' => 'آدرس صفحه اختصاصی (اختیاری)', 'type' => 'text']
    ]
];

try {
    $content->createModel('services', $serviceModel);
    echo '<p style="color:#16a34a; font-weight:bold;">✓ کالکشن خدمات (services) با ۸ فیلد تخصصی ساخته شد.</p>';
} catch (Throwable $e) {
    echo '<p style="color:#64748b;">ℹ وضعیت کالکشن خدمات: ' . htmlspecialchars($e->getMessage()) . '</p>';
}

// 3. Seed Articles (7 Full Articles with full content using saveItem)
$articles = json_decode(base64_decode(''), true);
$insertedArticles = 0;
$updatedArticles = 0;

foreach ($articles as $art) {
    try {
        $art['_state'] = 1; // Published
        $existing = $content->items('articles', ['filter' => ['slug' => $art['slug']]]);
        if (!empty($existing) && isset($existing[0]['_id'])) {
            $art['_id'] = $existing[0]['_id'];
            $res = $content->saveItem('articles', $art);
            if (!empty($res['_id'])) $updatedArticles++;
        } else {
            $res = $content->saveItem('articles', $art);
            if (!empty($res['_id'])) $insertedArticles++;
        }
    } catch (Throwable $e) {
        echo '<p style="color:red;">خطا در ثبت مقاله ' . htmlspecialchars($art['slug']) . ': ' . htmlspecialchars($e->getMessage()) . '</p>';
    }
}

// Check how many items actually exist in database
$actualArticles = $content->items('articles');
echo '<p style="color:#16a34a; font-weight:bold;">✓ تعداد مقالات ثبت‌شده در دیتابیس: ' . count($actualArticles) . ' مقاله (تأییدشده در دیتابیس Cockpit).</p>';

// 4. Seed Services (All 18 Services using saveItem)
$services = json_decode(base64_decode(''), true);
$insertedServices = 0;
$updatedServices = 0;

foreach ($services as $srv) {
    try {
        $srv['_state'] = 1; // Published
        $existing = $content->items('services', ['filter' => ['title' => $srv['title']]]);
        if (!empty($existing) && isset($existing[0]['_id'])) {
            $srv['_id'] = $existing[0]['_id'];
            $res = $content->saveItem('services', $srv);
            if (!empty($res['_id'])) $updatedServices++;
        } else {
            $res = $content->saveItem('services', $srv);
            if (!empty($res['_id'])) $insertedServices++;
        }
    } catch (Throwable $e) {
        echo '<p style="color:red;">خطا در ثبت خدمت ' . htmlspecialchars($srv['title']) . ': ' . htmlspecialchars($e->getMessage()) . '</p>';
    }
}

// Check how many services actually exist in database
$actualServices = $content->items('services');
echo '<p style="color:#16a34a; font-weight:bold;">✓ تعداد خدمات ثبت‌شده در دیتابیس: ' . count($actualServices) . ' خدمت (تأییدشده در دیتابیس Cockpit).</p>';

echo '<hr style="border:0; border-top:1px solid #e2e8f0; margin:25px 0;">';
echo '<h3 style="color:#16a34a; margin-bottom:8px;">🎉 انتقال کامل اطلاعات با موفقیت ۱۰۰٪ به پایان رسید!</h3>';
echo '<p>اکنون وارد پنل Cockpit شوید و بخش <b>Content</b> را باز کنید؛ تمام مقالات و ۱۸ کارت خدمات با تمام فیلدها و جزئیات دقیق نمایش داده می‌شوند.</p>';
echo '<p style="background:#fef2f2; color:#b91c1c; padding:14px; border-radius:10px; font-size:14px;">⚠️ <b>نکته امنیتی:</b> لطفاً پس از مشاهده موارد در پنل، این فایل (<code>seed.php</code>) را از پوشه <code>cms.fadakar-dev.ir</code> در File Manager هاست حذف کنید.</p>';
echo '</div>';
